import { useEffect, useState } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import { api, formatApiError } from "../lib/api";
import { useAuth } from "../lib/auth";
import { toast } from "sonner";
import LoadingSpinner from "../components/LoadingSpinner";
import SaveButton from "../components/SaveButton";
import ConfirmDialog from "../components/ConfirmDialog";
import { Compass, ArrowRight } from "lucide-react";

export default function AlbumUniverse() {
  const { id } = useParams();
  const { user, refreshUser } = useAuth();
  const navigate = useNavigate();
  const [d, setD] = useState(null);
  const [relationships, setRelationships] = useState(null);
  const [pathways, setPathways] = useState(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState({ title: "", universe_tagline: "" });

  useEffect(() => {
    setLoading(true);
    Promise.all([
      api.get(`/albums/${id}`),
      api.get(`/relationships/album/${id}`).catch(() => null),
      api.get(`/pathways/album/${id}`).catch(() => null),
    ])
      .then(([albumRes, relRes, pathRes]) => {
        setD(albumRes.data);
        setRelationships(relRes?.data || null);
        setPathways(pathRes?.data || null);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [id]);

  useEffect(() => {
    if (!d?.album) return;
    setForm({
      title: d.album.title || "",
      universe_tagline: d.album.universe_tagline || "",
    });
  }, [d]);

  if (loading) {
    return (
      <div className="dark-universe min-h-screen flex items-center justify-center">
        <div className="text-center meta">
          <LoadingSpinner size={24} />
          <div className="mt-4 mt-2">opening universe…</div>
        </div>
      </div>
    );
  }

  if (!d) return <div className="dark-universe min-h-screen flex items-center justify-center"><div className="meta">universe not found.</div></div>;

  const { album, artist, tracks = [], lore = [], theories = [], transitions = [] } = d;
  const motifs = Array.isArray(album?.motifs) ? album.motifs : [];
  const rel = relationships || { genre_adjacent: [], era_peers: [], artist_discography: [] };
  const pw = pathways || { next_worlds: [], timeline: null };
  const timeline = pw.timeline;

  return (
    <div className="dark-universe min-h-screen">
      <div className="max-w-[1480px] mx-auto px-6 py-14">
        {/* HEADER */}
        <div className="grid lg:grid-cols-12 gap-8 items-end">
          <div className="lg:col-span-7">
            <div className="meta mb-3" data-testid="album-universe-meta">universe · {album.year} · {artist?.name || album.artist_id}</div>
            {/* Timeline indicator */}
            {timeline && (
              <div className="meta mb-4 text-[var(--acid)]/80">
                {timeline.era_position} · {timeline.albums_before_in_era} before, {timeline.albums_after_in_era} after in this era
              </div>
            )}
            {user && (
              <div className="mt-3 flex flex-wrap gap-2">
                <SaveButton
                  type="album"
                  id={album.id}
                  saved={user.saved_album_ids?.includes(album.id)}
                  onToggle={() => refreshUser()}
                />
                {user.role === "admin" && (
                  <>
                    <button className="brutal-btn" onClick={() => setEditing((s) => !s)} disabled={actionLoading} data-testid="edit-album">{editing ? 'Cancel' : 'Edit'}</button>
                    <button className="brutal-btn" onClick={() => setConfirmDelete(true)} disabled={actionLoading} data-testid="delete-album">
                      {actionLoading ? <><LoadingSpinner size={16} /> <span className="ml-2">Deleting</span></> : 'Delete'}
                    </button>
                  </>
                )}
              </div>
            )}
            {!editing ? (
              <>
                <h1 className="font-display font-black text-7xl md:text-9xl tracking-tighter leading-[0.85]">{album.title}</h1>
                <p className="font-editorial italic text-2xl md:text-3xl mt-5">{album.universe_tagline}</p>
              </>
            ) : (
              <div className="space-y-3">
                <input className="input" value={form.title} onChange={(e) => setForm({...form, title:e.target.value})} />
                <input className="input" value={form.universe_tagline||''} onChange={(e) => setForm({...form, universe_tagline:e.target.value})} />
                <div className="flex gap-2">
                  <button className="brutal-btn" onClick={async ()=>{ setActionLoading(true); try { await api.put(`/albums/${album.id}`, { title: form.title, universe_tagline: form.universe_tagline }); const r = await api.get(`/albums/${album.id}`); setD(r.data); setEditing(false); toast.success('saved'); } catch (e) { toast.error(formatApiError(e.response?.data?.detail)); } finally { setActionLoading(false); } }} data-testid="save-album" disabled={actionLoading}>
                    {actionLoading ? <><LoadingSpinner size={16} /> <span className="ml-2">Saving</span></> : 'Save'}
                  </button>
                  <button className="brutal-btn" onClick={() => setEditing(false)} disabled={actionLoading}>Cancel</button>
                </div>
              </div>
            )}
            <div className="flex flex-wrap gap-2 mt-6">
              {motifs.map((m) => <span key={m} className="tag-chip hover:bg-white/10 transition-colors cursor-default">{m}</span>)}
            </div>
            {artist?.name && (
              <div className="mt-4">
                <Link to={`/explore?artist=${encodeURIComponent(artist.name)}`} className="font-editorial italic text-xl underline underline-offset-4 decoration-1 hover:decoration-2 transition-all">
                  more from {artist.name} →
                </Link>
              </div>
            )}
            {/* Genre predecessors */}
            {timeline?.genre_predecessors?.length > 0 && (
              <div className="mt-4 meta">
                earlier in this lineage: {timeline.genre_predecessors.map((p) => (
                  <Link key={p.id} to={`/album/${p.id}`} className="underline underline-offset-2 ml-1">{p.title} ({p.year})</Link>
                ))}
              </div>
            )}
          </div>
          <div className="lg:col-span-5">
            <div className="aspect-square w-full relative" style={{ background: album.color }}>
              <div className="absolute inset-0 grain" />
              <div className="absolute inset-6 border-2 border-[var(--parchment)] flex flex-col justify-between p-6">
                <span className="meta-ink mix-blend-multiply">cover · stylized</span>
                <span className="font-display font-black text-5xl tracking-tighter text-[var(--parchment)] mix-blend-multiply">{album.title.toLowerCase()}</span>
              </div>
            </div>
          </div>
        </div>

        {/* TRACKS */}
        <section className="mt-14">
          <div className="meta mb-3">tracklist · the inhabitable world</div>
          <h2 className="font-display font-black text-3xl tracking-tighter mb-6">walk through it.</h2>
          <div className="border-2 border-[var(--parchment)] divide-y-2 divide-[var(--parchment)]">
            {tracks.map((t, i) => (
              <Link key={t.id} to={`/track/${t.id}`} className="flex items-center gap-4 px-5 py-4 hover:bg-white/5 transition-colors group" data-testid={`album-track-${t.id}`}>
                <span className="meta group-hover:text-[var(--acid)] transition-colors">{String(i+1).padStart(2,'0')}</span>
                <span className="font-display font-bold text-xl flex-1">{t.title}</span>
                <span className="meta hidden md:inline italic font-editorial !text-[var(--parchment)]/70 !text-sm normal-case tracking-normal">"{t.key_line}"</span>
                <span className="meta">{t.duration}</span>
              </Link>
            ))}
          </div>
        </section>

        {/* TRANSITIONS */}
        {transitions?.length > 0 && (
          <section className="mt-14">
            <div className="meta mb-3">transition culture</div>
            <h2 className="font-display font-black text-3xl tracking-tighter mb-4">the moments between songs.</h2>
            <div className="grid md:grid-cols-2 gap-4">
              {transitions.map((t) => (
                <div key={t.id} className="brutal-card-static p-5" data-testid={`transition-${t.id}`}>
                  <div className="meta-ink">{t.type}</div>
                  <div className="font-display font-bold text-lg mt-1">{t.from_track} → {t.to_track}</div>
                  <p className="font-editorial italic mt-2">{t.notes}</p>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* NEXT WORLDS — smart "enter this world" pathways */}
        {pw.next_worlds?.length > 0 && (
          <section className="mt-14">
            <div className="meta mb-3 flex items-center gap-2"><Compass size={12} /> enter from here</div>
            <h2 className="font-display font-black text-3xl tracking-tighter mb-6">worlds you should visit next.</h2>
            <div className="flex gap-4 overflow-x-auto pb-4 -mx-6 px-6 snap-x">
              {pw.next_worlds.map((w) => (
                <Link key={w.id} to={`/album/${w.id}`} className="snap-start flex-shrink-0 w-64 group">
                  <div className="aspect-[4/3] relative grain" style={{ background: w.color || '#222' }}>
                    <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors" />
                    <div className="absolute inset-3 border border-[var(--parchment)]/20 p-3 flex flex-col justify-between">
                      <span className="meta text-[10px] text-[var(--acid)]/80">{w._pathway_label || 'pathway'}</span>
                      <span className="font-display font-black text-xl tracking-tighter text-[var(--parchment)]">{w.title.toLowerCase()}</span>
                    </div>
                  </div>
                  <div className="mt-2">
                    <div className="font-display font-bold text-sm">{w.artist_name}</div>
                    <div className="meta-ink text-[10px]">{w._pathway_reason}</div>
                  </div>
                </Link>
              ))}
            </div>
          </section>
        )}

        {/* RELATED PATHWAYS — genre, era, discography */}
        {(rel.genre_adjacent?.length > 0 || rel.era_peers?.length > 0 || rel.artist_discography?.length > 0) && (
          <section className="mt-14">
            <div className="meta mb-3">pathways</div>
            <h2 className="font-display font-black text-3xl tracking-tighter mb-6">worlds you can enter from here.</h2>
            
            <div className="space-y-8">
              {rel.genre_adjacent?.length > 0 && (
                <div>
                  <div className="meta-ink mb-3">genre adjacency</div>
                  <div className="flex gap-4 overflow-x-auto pb-4 -mx-6 px-6 snap-x">
                    {rel.genre_adjacent.map((a) => (
                      <Link key={a.id} to={`/album/${a.id}`} className="snap-start flex-shrink-0 w-56 group">
                        <div className="aspect-[4/3] relative grain" style={{ background: a.color || '#333' }}>
                          <div className="absolute inset-3 border border-[var(--parchment)]/30 p-3 flex flex-col justify-between group-hover:border-[var(--parchment)] transition-colors">
                            <span className="meta text-[10px]">{a.year}</span>
                            <span className="font-display font-black text-lg tracking-tighter text-[var(--parchment)]">{a.title.toLowerCase()}</span>
                          </div>
                        </div>
                        <p className="font-editorial italic text-sm mt-2 line-clamp-2">{a.universe_tagline || a._shared_genres?.slice(0,2).join(', ')}</p>
                      </Link>
                    ))}
                  </div>
                </div>
              )}

              {rel.era_peers?.length > 0 && (
                <div>
                  <div className="meta-ink mb-3">same era · {rel.era_peers[0]._era}</div>
                  <div className="flex gap-4 overflow-x-auto pb-4 -mx-6 px-6 snap-x">
                    {rel.era_peers.map((a) => (
                      <Link key={a.id} to={`/album/${a.id}`} className="snap-start flex-shrink-0 w-56 group">
                        <div className="aspect-[4/3] relative grain" style={{ background: a.color || '#333' }}>
                          <div className="absolute inset-3 border border-[var(--parchment)]/30 p-3 flex flex-col justify-between group-hover:border-[var(--parchment)] transition-colors">
                            <span className="meta text-[10px]">{a.year}</span>
                            <span className="font-display font-black text-lg tracking-tighter text-[var(--parchment)]">{a.title.toLowerCase()}</span>
                          </div>
                        </div>
                        <p className="font-editorial italic text-sm mt-2 line-clamp-2">{a.artist_name}</p>
                      </Link>
                    ))}
                  </div>
                </div>
              )}

              {rel.artist_discography?.length > 0 && (
                <div>
                  <div className="meta-ink mb-3">more from {rel.artist_discography[0].artist_name}</div>
                  <div className="flex gap-4 overflow-x-auto pb-4 -mx-6 px-6 snap-x">
                    {rel.artist_discography.map((a) => (
                      <Link key={a.id} to={`/album/${a.id}`} className="snap-start flex-shrink-0 w-56 group">
                        <div className="aspect-[4/3] relative grain" style={{ background: a.color || '#333' }}>
                          <div className="absolute inset-3 border border-[var(--parchment)]/30 p-3 flex flex-col justify-between group-hover:border-[var(--parchment)] transition-colors">
                            <span className="meta text-[10px]">{a.year}</span>
                            <span className="font-display font-black text-lg tracking-tighter text-[var(--parchment)]">{a.title.toLowerCase()}</span>
                          </div>
                        </div>
                        <p className="font-editorial italic text-sm mt-2 line-clamp-2">{a.universe_tagline}</p>
                      </Link>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </section>
        )}

        {/* LORE + THEORIES */}
        <section className="mt-14 grid lg:grid-cols-2 gap-8">
          <div>
            <div className="meta mb-3">album lore</div>
            <h2 className="font-display font-black text-3xl tracking-tighter mb-4">what's been written.</h2>
            <div className="space-y-3">
              {lore.map((l) => (
                <Link key={l.id} to={`/lore/${l.id}`} className="brutal-card-static p-5 block hover:bg-white/5 transition-colors" data-testid={`album-lore-${l.id}`}>
                  <div className="meta-ink">by {l.author} · {l.depth}</div>
                  <div className="font-display font-bold text-xl mt-1">{l.title}</div>
                  <p className="font-editorial italic mt-2">{l.excerpt}</p>
                </Link>
              ))}
              {lore.length === 0 && <p className="meta">no lore yet — start writing it.</p>}
            </div>
          </div>
          <div>
            <div className="meta mb-3">theories</div>
            <h2 className="font-display font-black text-3xl tracking-tighter mb-4">what's contested.</h2>
            <div className="space-y-3">
              {theories.map((t) => (
                <Link key={t.id} to={`/theory/${t.id}`} className="brutal-card-static p-5 block hover:bg-white/5 transition-colors" data-testid={`album-theory-${t.id}`}>
                  <div className="meta-ink">{t.stance} · by {t.author}</div>
                  <div className="font-display font-bold text-xl mt-1">{t.title}</div>
                  <p className="font-editorial italic mt-2">{t.abstract}</p>
                </Link>
              ))}
              {theories.length === 0 && <p className="meta">no theories yet.</p>}
            </div>
          </div>
        </section>
      </div>

      <ConfirmDialog
        open={confirmDelete}
        title="Delete album"
        description="Delete this album? This action cannot be undone."
        confirmLabel="Delete"
        cancelLabel="Cancel"
        danger
        loading={actionLoading}
        onCancel={() => setConfirmDelete(false)}
        onConfirm={async () => {
          setActionLoading(true);
          try {
            await api.delete(`/albums/${album.id}`);
            toast.success('deleted');
            navigate('/');
          } catch (e) {
            toast.error(formatApiError(e.response?.data?.detail));
          } finally {
            setActionLoading(false);
            setConfirmDelete(false);
          }
        }}
      />
    </div>
  );
}
